-- Immutable legal releases and explicit, account-scoped acceptance evidence.
CREATE TABLE legal_documents (
 document_type varchar(32) NOT NULL,
 version varchar(40) NOT NULL,
 acceptance_revision varchar(40) NOT NULL,
 locale varchar(8) NOT NULL CHECK (locale IN ('es','en')),
 content_hash char(64) NOT NULL,
 title text NOT NULL,
 summary text NOT NULL,
 sections jsonb NOT NULL,
 published_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY (document_type, version, locale),
 UNIQUE (document_type, version, locale, acceptance_revision, content_hash)
);
CREATE TABLE user_legal_acceptances (
 user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 document_type varchar(32) NOT NULL,
 acceptance_revision varchar(40) NOT NULL,
 document_version varchar(40) NOT NULL,
 locale varchar(8) NOT NULL,
 content_hash char(64) NOT NULL,
 accepted_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY (user_id, document_type, acceptance_revision),
 FOREIGN KEY (document_type, document_version, locale, acceptance_revision, content_hash)
   REFERENCES legal_documents(document_type, version, locale, acceptance_revision, content_hash)
);
COMMENT ON TABLE user_legal_acceptances IS 'Explicit acceptance only; no backfill for existing users. Deleted with account.';
CREATE INDEX idx_user_legal_acceptances_document ON user_legal_acceptances
 (document_type, document_version, locale, acceptance_revision, content_hash);
-- Corrections are new releases, not rewrites of what a user accepted.
CREATE FUNCTION reject_legal_evidence_rewrite() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 RAISE EXCEPTION 'Legal evidence is immutable; publish a new version';
END;
$$;
CREATE TRIGGER legal_documents_immutable BEFORE UPDATE OR DELETE ON legal_documents
 FOR EACH ROW EXECUTE FUNCTION reject_legal_evidence_rewrite();
CREATE TRIGGER legal_acceptance_immutable BEFORE UPDATE ON user_legal_acceptances
 FOR EACH ROW EXECUTE FUNCTION reject_legal_evidence_rewrite();
INSERT INTO legal_documents(document_type,version,acceptance_revision,locale,content_hash,title,summary,sections) VALUES ('terms','2026-09-27.1','terms-1','es','80470d6ff8278c96b918a5c72ff11ebd6b73092d659816316d1df46c44f73f2d','Términos de uso','El alcance del servicio y las reglas para utilizar Vinnot.','[{"id":"service","title":"Qué ofrece Vinnot","body":"Vinnot es una plataforma de descubrimiento y gestión de vinos, reseñas, cava personal, bodegas, eventos y rutas. El titular identificado en el centro legal opera la plataforma. Estos términos describen el uso de sus funciones; las condiciones específicas de cada evento deben consultarse antes de inscribirse."},{"id":"account","title":"Tu cuenta y su seguridad","body":"Utilizá datos de contacto propios y mantenelos actualizados. Protegé tus credenciales y no uses cuentas ajenas ni suplantes a otras personas. Los permisos de administración, moderación y organización se limitan a las acciones autorizadas para cada rol. Si sospechás un acceso no autorizado, cambiá la contraseña y contactanos."},{"id":"responsible","title":"Uso responsable","body":"Las funciones vinculadas con bebidas alcohólicas no deben utilizarse para promover su consumo por menores ni para eludir controles de edad de un organizador o establecimiento. Respetá las restricciones aplicables en tu lugar de residencia y en cada actividad. Vinnot no es un servicio médico ni una recomendación para consumir alcohol."},{"id":"content","title":"Contenido y aportes","body":"Conservás los derechos que te correspondan sobre tus aportes. Al enviar una reseña, foto o propuesta, autorizás el uso necesario para alojarla, mostrarla y revisarla dentro del servicio. No publiques material sobre el que no tengas derechos, datos privados de terceros o contenido engañoso. Las normas de comunidad y moderación explican los criterios aplicables."},{"id":"information","title":"Catálogo, escaneo e inteligencia artificial","body":"La información puede estar incompleta o desactualizada. Revisá la etiqueta y la ficha del productor para datos como alcohol, alérgenos, origen y composición. Un resultado de escaneo requiere verificar nombre, línea y variedad. El contenido generado con IA puede contener inferencias y errores; no constituye una certificación, diagnóstico ni garantía sobre una botella."},{"id":"transactions","title":"Eventos y servicios de terceros","body":"Actualmente Vinnot no vende botellas ni ofrece suscripciones premium. Los organizadores gestionan el cobro de sus eventos fuera del procesamiento de pagos de Vinnot. Consultá precio, disponibilidad, requisitos y cancelaciones con el organizador. No se aplican comisiones futuras a operaciones actuales por el solo anuncio de un proyecto de integración."},{"id":"restrictions","title":"Restricciones y revisión","body":"No intentes acceder sin autorización, automatizar abuso, manipular puntuaciones ni interferir con el servicio. Ante incumplimientos pueden revisarse contenidos o restringirse accesos conforme a la política de moderación. Podés solicitar revisión por Contacto identificando la decisión. Una restricción no elimina los derechos que te reconozca la legislación aplicable."},{"id":"changes","title":"Cambios, baja y consultas","body":"Podés gestionar la baja de tu cuenta desde las opciones disponibles en el perfil o consultar por Contacto. Las modificaciones del servicio o de estos términos se identificarán mediante una versión actualizada; no se atribuye una aceptación retroactiva a usuarios existentes. Ninguna disposición pretende excluir derechos irrenunciables ni las responsabilidades que legalmente correspondan."}]'::jsonb);
INSERT INTO legal_documents(document_type,version,acceptance_revision,locale,content_hash,title,summary,sections) VALUES ('terms','2026-09-27.1','terms-1','en','559ea607bf3a2ae2fb79a446ba16457eefba69be6737035e0ce7dbc34f128d5f','Terms of use','The scope of the service and the rules for using Vinnot.','[{"id":"service","title":"What Vinnot offers","body":"Vinnot is a platform for wine discovery and management, reviews, personal cellars, wineries, events and routes. The operator identified in the legal centre runs the platform. These terms describe the use of its features; the conditions of each event should be checked before registering."},{"id":"account","title":"Your account and its security","body":"Use your own contact details and keep them up to date. Protect your credentials and do not use other people''s accounts or impersonate others. Administration, moderation and organiser permissions are limited to the actions authorised for each role. If you suspect unauthorised access, change your password and contact us."},{"id":"responsible","title":"Responsible use","body":"Features relating to alcoholic beverages must not be used to promote consumption by minors or bypass an organiser''s or establishment''s age controls. Follow restrictions applicable where you live and at each activity. Vinnot is not a medical service or a recommendation to consume alcohol."},{"id":"content","title":"Content and contributions","body":"You retain the rights you hold in your contributions. When you submit a review, photo or proposal, you authorise the use necessary to host, display and review it within the service. Do not publish material you have no right to use, private information about others or misleading content. The community and moderation policies explain the applicable criteria."},{"id":"information","title":"Catalogue, scanning and artificial intelligence","body":"Information may be incomplete or outdated. Check the label and producer''s technical sheet for details such as alcohol, allergens, origin and composition. A scan result requires checking the name, product line and variety. AI-generated content may contain inferences and errors; it is not certification, a diagnosis or a guarantee about a bottle."},{"id":"transactions","title":"Events and third-party services","body":"Vinnot currently does not sell bottles or offer premium subscriptions. Organisers manage payment for their events outside Vinnot payment processing. Check price, availability, requirements and cancellations with the organiser. Future commissions do not apply to current transactions merely because an integration is being considered."},{"id":"restrictions","title":"Restrictions and review","body":"Do not attempt unauthorised access, automate abuse, manipulate ratings or interfere with the service. Breaches may result in content review or access restrictions under the moderation policy. You can request review through Contact by identifying the decision. A restriction does not remove rights granted by applicable law."},{"id":"changes","title":"Changes, account closure and questions","body":"You can manage account closure through the available profile options or ask through Contact. Changes to the service or these terms will be identified through an updated version; no retroactive acceptance is attributed to existing users. No provision is intended to exclude mandatory rights or responsibilities imposed by law."}]'::jsonb);
